contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this)); }
    function testFuzz_property(uint256 amount, address pool) public {
        vm.assume(pool != address(0) && pool != address(c));
        vm.assume(amount > 0 && amount < type(uint256).max / 2);

        // Simulate mintSynth by directly manipulating state to bypass onlyPool modifier
        // We need the pool to be a curated pool; we can't easily set that up without the full system.
        // Instead, we'll directly call mintSynth using a low-level call to the contract's internal
        // state through a helper that has the onlyPool modifier bypassed via a prank from a "curated" pool.
        // Since we can't set a curated pool without deploying the full factory, we'll use a cheat:
        // we'll deploy a minimal pool mock that is considered curated by overriding the DAO/POOLFACTORY.
        // But the test must only observe c. Let's use a different approach: we'll call allowance to trigger
        // the property check after mintSynth. However, mintSynth requires onlyPool, which checks isCuratedPool.
        // We can make the test contract a curated pool by deploying a fake factory that returns true,
        // but that's complex. Instead, we'll use the fact that the test contract can be the DEPLOYER (DAO)
        // and call directly via a prank, but mintSynth is onlyPool, not onlyDAO. 
        // We'll note: the bug is in mintSynth, which is callable by any curated pool. We'll make the test
        // contract pass as a curated pool by deploying a minimal POOLFACTORY that says it is.
        // However, the instructions say we must observe through allowance(), so we need a sequence that
        // includes a call to allowance(). We can call allowance after mintSynth.
        // We'll deploy a helper that acts as a curated pool and calls mintSynth.
    }
}

