contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this)); }
    function testFuzz_property(uint256 amount, uint256 burnAmount) public {
        // Bound inputs to reasonable ranges
        vm.assume(amount > 0 && amount < type(uint128).max);
        vm.assume(burnAmount > 0 && burnAmount <= amount);

        // Deploy a minimal pool helper that allows c to act as onlyPool
        address pool = address(new PoolHelper(c));

        // Simulate the pool calling mintSynth
        vm.prank(pool);
        c.mintSynth(address(this), amount);

        // Calculate expected LPBalance after burn: should be zero because we burn all LPDebt
        uint256 lpBalanceBeforeBurn = c.mapSynth_LPBalance(pool);
        uint256 lpDebtBeforeBurn = c.mapSynth_LPDebt(pool);

        // Send burnAmount to c and trigger burnSynth from pool context
        vm.prank(address(c));
        c.transfer(address(c), burnAmount);

        vm.prank(pool);
        c.burnSynth();

        // After burning all debt (burnAmount == amount), the LPBalance should be 0
        // The bug adds +1 to debt per mintSynth causing mapSynth_LPBalance to be non-zero after burning
        assertTrue(c.mapSynth_LPBalance(pool) == 0);
    }
}

contract PoolHelper {
    C public synth;
    constructor(C _synth) { synth = _synth; }
